1	<!DOCTYPE html>
2	<!--
3	  PRD Validation Report — skeleton template.
4	
5	  This file is a starter the synthesis pass fills in directly. There is no
6	  substitution engine. The LLM:
7	    1. Reads {doc_workspace}/review-rubric.md and every review-{slug}.md from
8	       additional reviewers.
9	    2. Copies this skeleton.
10	    3. Replaces the placeholder content (everything between TEMPLATE markers)
11	       with the consolidated review, preserving the structure and CSS.
12	    4. Writes the result to {doc_workspace}/validation-report.html.
13	    5. Writes a markdown twin to {doc_workspace}/validation-report.md.
14	
15	  Visual rules the LLM must preserve:
16	    - The container width, the color tokens, the typography.
17	    - One dimension = one collapsible <section class="dimension">.
18	    - Verdict pill uses the verdict-* class matching its judgment.
19	    - Severity badge uses the sev-* class matching its level.
20	    - Each extra reviewer (adversarial, etc.) gets its own collapsible section
21	      below the rubric dimensions.
22	    - The footer always shows the artifact paths and timestamp.
23	-->
24	<html lang="en">
25	<head>
26	<meta charset="utf-8">
27	<title>PRD Validation: TEMPLATE_PRD_NAME</title>
28	<style>
29	  :root {
30	    --bg: #fafaf9;
31	    --surface: #ffffff;
32	    --border: #e7e5e4;
33	    --text: #1c1917;
34	    --muted: #78716c;
35	
36	    --verdict-strong: #16a34a;
37	    --verdict-adequate: #65a30d;
38	    --verdict-thin: #d97706;
39	    --verdict-broken: #dc2626;
40	
41	    --sev-low: #64748b;
42	    --sev-medium: #ca8a04;
43	    --sev-high: #ea580c;
44	    --sev-critical: #dc2626;
45	
46	    --grade-exc: #16a34a;
47	    --grade-good: #65a30d;
48	    --grade-fair: #d97706;
49	    --grade-poor: #dc2626;
50	  }
51	  * { box-sizing: border-box; }
52	  html, body { margin: 0; padding: 0; }
53	  body {
54	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, system-ui, sans-serif;
55	    background: var(--bg);
56	    color: var(--text);
57	    line-height: 1.6;
58	    font-size: 15px;
59	  }
60	  .container { max-width: 960px; margin: 0 auto; padding: 32px 24px 64px; }
61	
62	  header.report-header {
63	    display: flex;
64	    align-items: flex-start;
65	    justify-content: space-between;
66	    gap: 24px;
67	    padding-bottom: 16px;
68	    border-bottom: 1px solid var(--border);
69	    margin-bottom: 24px;
70	  }
71	  .title h1 { margin: 0; font-size: 22px; font-weight: 600; letter-spacing: -0.01em; }
72	  .title .subtitle { color: var(--muted); font-size: 13px; margin-top: 4px; font-family: ui-monospace, "SF Mono", Menlo, monospace; }
73	  .grade {
74	    padding: 10px 18px;
75	    border-radius: 8px;
76	    font-weight: 600;
77	    color: white;
78	    font-size: 15px;
79	    white-space: nowrap;
80	  }
81	  .grade-excellent { background: var(--grade-exc); }
82	  .grade-good { background: var(--grade-good); }
83	  .grade-fair { background: var(--grade-fair); }
84	  .grade-poor { background: var(--grade-poor); }
85	
86	  .synthesis {
87	    background: var(--surface);
88	    border: 1px solid var(--border);
89	    border-left: 3px solid var(--muted);
90	    border-radius: 8px;
91	    padding: 18px 22px;
92	    margin-bottom: 24px;
93	    font-size: 15.5px;
94	  }
95	  .synthesis p { margin: 0 0 10px; }
96	  .synthesis p:last-child { margin-bottom: 0; }
97	
98	  .dimension-summary {
99	    display: grid;
100	    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
101	    gap: 10px;
102	    margin-bottom: 24px;
103	  }
104	  .dim-card {
105	    background: var(--surface);
106	    border: 1px solid var(--border);
107	    border-radius: 8px;
108	    padding: 12px 14px;
109	  }
110	  .dim-card .dim-name { font-size: 13px; color: var(--muted); margin-bottom: 6px; }
111	  .dim-card .dim-verdict { font-size: 14px; font-weight: 600; }
112	
113	  section.dimension, section.reviewer-section { margin-bottom: 14px; }
114	  section.dimension details, section.reviewer-section details {
115	    background: var(--surface);
116	    border: 1px solid var(--border);
117	    border-radius: 8px;
118	    overflow: hidden;
119	  }
120	  section summary {
121	    padding: 14px 20px;
122	    cursor: pointer;
123	    user-select: none;
124	    list-style: none;
125	    display: flex;
126	    align-items: center;
127	    gap: 12px;
128	  }
129	  section summary::-webkit-details-marker { display: none; }
130	  section summary::before {
131	    content: "▸";
132	    display: inline-block;
133	    color: var(--muted);
134	    transition: transform 0.15s ease;
135	  }
136	  section details[open] summary::before { transform: rotate(90deg); }
137	  section summary h2 {
138	    display: inline;
139	    margin: 0;
140	    font-size: 16px;
141	    font-weight: 600;
142	    letter-spacing: -0.005em;
143	    flex: 1;
144	  }
145	  .verdict-pill {
146	    font-size: 11px;
147	    padding: 3px 10px;
148	    border-radius: 999px;
149	    font-weight: 600;
150	    text-transform: uppercase;
151	    letter-spacing: 0.04em;
152	    color: white;
153	  }
154	  .verdict-strong { background: var(--verdict-strong); }
155	  .verdict-adequate { background: var(--verdict-adequate); }
156	  .verdict-thin { background: var(--verdict-thin); }
157	  .verdict-broken { background: var(--verdict-broken); }
158	
159	  .dim-body { padding: 4px 20px 18px; }
160	  .dim-judgment { color: var(--text); font-size: 14.5px; }
161	  .dim-judgment p { margin: 0 0 10px; }
162	
163	  .findings-list { padding: 0 20px 4px; }
164	  article.finding {
165	    padding: 14px 0;
166	    border-top: 1px solid var(--border);
167	  }
168	  article.finding:first-child { border-top: none; }
169	  article.finding header {
170	    display: flex;
171	    align-items: center;
172	    gap: 10px;
173	    flex-wrap: wrap;
174	    margin-bottom: 6px;
175	  }
176	  .badge {
177	    font-size: 10.5px;
178	    padding: 3px 8px;
179	    border-radius: 4px;
180	    font-weight: 600;
181	    text-transform: uppercase;
182	    letter-spacing: 0.04em;
183	    line-height: 1.4;
184	  }
185	  .badge-sev-low { background: rgba(100, 116, 139, 0.12); color: var(--sev-low); }
186	  .badge-sev-medium { background: rgba(202, 138, 4, 0.14); color: var(--sev-medium); }
187	  .badge-sev-high { background: rgba(234, 88, 12, 0.14); color: var(--sev-high); }
188	  .badge-sev-critical { background: rgba(220, 38, 38, 0.14); color: var(--sev-critical); }
189	  .finding-title { margin: 0; font-size: 15px; font-weight: 500; flex: 1; min-width: 200px; }
190	  .finding-location { font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 12.5px; color: var(--muted); }
191	  .finding-note, .finding-fix { margin-top: 6px; font-size: 14px; }
192	  .finding-fix strong { color: var(--muted); font-weight: 500; }
193	
194	  .reviewer-source {
195	    font-size: 12px;
196	    color: var(--muted);
197	    font-family: ui-monospace, "SF Mono", Menlo, monospace;
198	  }
199	
200	  .mechanical {
201	    background: var(--surface);
202	    border: 1px solid var(--border);
203	    border-radius: 8px;
204	    padding: 16px 20px;
205	    margin-top: 24px;
206	    font-size: 14px;
207	  }
208	  .mechanical h3 { margin: 0 0 10px; font-size: 14px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.04em; }
209	  .mechanical ul { margin: 0; padding-left: 20px; }
210	  .mechanical li { margin-bottom: 4px; color: var(--text); }
211	
212	  footer.report-footer {
213	    margin-top: 40px;
214	    padding-top: 16px;
215	    border-top: 1px solid var(--border);
216	    font-size: 12px;
217	    color: var(--muted);
218	    font-family: ui-monospace, "SF Mono", Menlo, monospace;
219	  }
220	  footer .meta { display: flex; gap: 24px; flex-wrap: wrap; }
221	</style>
222	</head>
223	<body>
224	  <div class="container">
225	
226	    <!-- TEMPLATE: header. Fill prd name, prd path, grade text & class. -->
227	    <header class="report-header">
228	      <div class="title">
229	        <h1>TEMPLATE_PRD_NAME — Validation Report</h1>
230	        <div class="subtitle">TEMPLATE_PRD_PATH</div>
231	      </div>
232	      <div class="grade TEMPLATE_GRADE_CLASS">TEMPLATE_GRADE</div>
233	    </header>
234	
235	    <!-- TEMPLATE: overall synthesis paragraphs. Lift directly from
236	         review-rubric.md "Overall verdict" section; expand if extra reviewers
237	         materially shift the picture. Wrap each paragraph in <p>. -->
238	    <div class="synthesis">
239	      <p>TEMPLATE_SYNTHESIS_PARAGRAPH</p>
240	    </div>
241	
242	    <!-- TEMPLATE: dimension summary cards. One per rubric dimension. The
243	         dim-verdict text uses one of: strong | adequate | thin | broken. -->
244	    <div class="dimension-summary">
245	      <div class="dim-card">
246	        <div class="dim-name">Decision-readiness</div>
247	        <div class="dim-verdict" style="color: var(--verdict-TEMPLATE_VERDICT)">TEMPLATE_VERDICT_TEXT</div>
248	      </div>
249	      <!-- repeat for each of the seven dimensions -->
250	    </div>
251	
252	    <!-- TEMPLATE: one section per rubric dimension. Skip a dimension entirely
253	         if the rubric review marked it n/a for this PRD (e.g. downstream
254	         usability for a standalone PRD). Open the section by default if
255	         verdict is thin or broken. -->
256	    <section class="dimension">
257	      <details open>
258	        <summary>
259	          <h2>Decision-readiness</h2>
260	          <span class="verdict-pill verdict-TEMPLATE_VERDICT">TEMPLATE_VERDICT_TEXT</span>
261	        </summary>
262	        <div class="dim-body">
263	          <div class="dim-judgment">
264	            <p>TEMPLATE_DIMENSION_JUDGMENT</p>
265	          </div>
266	        </div>
267	        <div class="findings-list">
268	          <!-- TEMPLATE: zero or more findings -->
269	          <article class="finding">
270	            <header>
271	              <span class="badge badge-sev-TEMPLATE_SEVERITY">TEMPLATE_SEVERITY</span>
272	              <h3 class="finding-title">TEMPLATE_FINDING_TITLE</h3>
273	              <span class="finding-location">TEMPLATE_LOCATION</span>
274	            </header>
275	            <div class="finding-note">TEMPLATE_FINDING_NOTE</div>
276	            <div class="finding-fix"><strong>Fix:</strong> TEMPLATE_SUGGESTED_FIX</div>
277	          </article>
278	        </div>
279	      </details>
280	    </section>
281	
282	    <!-- TEMPLATE: one section per extra reviewer that ran (adversarial, etc.).
283	         Skip this block entirely if only the rubric walker ran. -->
284	    <section class="reviewer-section">
285	      <details>
286	        <summary>
287	          <h2>Adversarial review</h2>
288	          <span class="reviewer-source">TEMPLATE_REVIEWER_SOURCE_FILE</span>
289	        </summary>
290	        <div class="dim-body">
291	          <div class="dim-judgment">
292	            <p>TEMPLATE_REVIEWER_PREAMBLE</p>
293	          </div>
294	        </div>
295	        <div class="findings-list">
296	          <article class="finding">
297	            <header>
298	              <span class="badge badge-sev-TEMPLATE_SEVERITY">TEMPLATE_SEVERITY</span>
299	              <h3 class="finding-title">TEMPLATE_FINDING_TITLE</h3>
300	              <span class="finding-location">TEMPLATE_LOCATION</span>
301	            </header>
302	            <div class="finding-note">TEMPLATE_FINDING_NOTE</div>
303	            <div class="finding-fix"><strong>Fix:</strong> TEMPLATE_SUGGESTED_FIX</div>
304	          </article>
305	        </div>
306	      </details>
307	    </section>
308	
309	    <!-- TEMPLATE: mechanical notes — short, bulleted. Skip if there are none. -->
310	    <div class="mechanical">
311	      <h3>Mechanical notes</h3>
312	      <ul>
313	        <li>TEMPLATE_MECHANICAL_NOTE</li>
314	      </ul>
315	    </div>
316	
317	    <footer class="report-footer">
318	      <div class="meta">
319	        <span>Rubric: TEMPLATE_RUBRIC_PATH</span>
320	        <span>Generated: TEMPLATE_TIMESTAMP</span>
321	      </div>
322	    </footer>
323	  </div>
324	</body>
325	</html>
